mapper.select:
SELECT * FROM queue_ticket WHERE outlet_id=#{outlet} AND service_date=#{date}
AND status='WAITING' AND item_id IN
#{item}
ORDER BY priority DESC, checked_in_at ASC, id ASC LIMIT 1 FOR UPDATE SKIP LOCKED

mapper.update:
UPDATE queue_ticket SET status=#{to}, version=version+1, updated_at=UTC_TIMESTAMP(3),
called_at=UTC_TIMESTAMP(3),called_window_id=#{window},work_session_id=#{session},call_count=call_count+1, called_at=UTC_TIMESTAMP(3),call_count=call_count+1, serving_at=UTC_TIMESTAMP(3), missed_at=UTC_TIMESTAMP(3), completed_at=UTC_TIMESTAMP(3),result_code=#{result},
id=id WHERE id=#{id} AND status=#{from} AND version=#{version} AND called_window_id=#{window} AND work_session_id=#{session}

mapper.select:
SELECT * FROM queue_ticket WHERE user_id=#{user} AND service_date=#{date}
AND appointment_id=#{appointment}
ORDER BY id DESC LIMIT 20

SELECT item_id AS itemId,called_window_id AS windowId,status,COUNT(*) AS count
FROM queue_ticket WHERE outlet_id=#{outlet} AND service_date=#{date}
GROUP BY item_id,called_window_id,status ORDER BY item_id,called_window_id,status
